SELECT assays.chembl_id AS assay_chembl_id, td.target_type, td.tax_id, cs.canonical_smiles, md.chembl_id AS molecule_chembl_id, act.standard_type, act.pchembl_value FROM activities act JOIN assays assays ON act.assay_id = assays.assay_id JOIN target_dictionary td ON assays.tid = td.tid JOIN molecule_dictionary md ON act.molregno = md.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE td.chembl_id = 'CHEMBL1075104' AND td.target_type = 'SINGLE PROTEIN' AND td.tax_id = 9606 AND act.standard_type = 'IC50' AND act.standard_relation = '=' AND act.pchembl_value IS NOT NULL ORDER BY md.chembl_id ASC, assays.chembl_id ASC LIMIT 1000
